import{_ as t,a as o}from"./chunks/4-2.D72cDERm.js";import{_ as s,o as i,c as n,a4 as a}from"./chunks/framework.BI9De5Cr.js";const _=JSON.parse('{"title":"Safety Device Mounting Location","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety_function/safety_device_mounting_location.md","filePath":"manual/safety_function/safety_device_mounting_location.md"}'),r={name:"manual/safety_function/safety_device_mounting_location.md"};function c(d,e,p,u,h,l){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="safety-device-mounting-location" tabindex="-1">Safety Device Mounting Location <a class="header-anchor" href="#safety-device-mounting-location" aria-label="Permalink to &quot;Safety Device Mounting Location&quot;">​</a></h1><p>In addition to the basic emergency stop switch, the RB Series can be equipped with additional safety devices required by the system integrator through risk assessment.</p><p>The safety-dedicated contact terminal consists of 16 ports. This terminal is a redundant dedicated contact input terminal.</p><p><img src="'+t+'" alt="missing"></p><p>The additional ports can be equipped with 4 equipment. The robot is delivered with a default configuration, which enables operation without any additional safety equipment.</p><p>When using without connecting an external safety device, connect and use the basic contact input as shown below.</p><p><img src="'+o+'" alt="missing"></p><p>Safety device port specifications are as follows.</p><ul><li><p><strong>EMO</strong><br> This port is used when it is necessary to install an extra emergency stop switch through risk assessment.<br> The emergency stop switch should be used as a product conforming to IEC 60947-5-5.<br> Emergency stop generated through EMO is designated as stop category 1.</p></li><li><p><strong>PRS</strong><br> This port is used to connect one or more protective stop devices through risk assessment.<br> Protective stop devices must be used in accordance with 5.3.8.3 of ISO 10218-2.<br> Protection stops occurring through PRS are designated as stop category 1.</p></li><li><p><strong>HSS</strong><br> This port is used to connect one or more protective stop devices through risk assessment.<br> Protective stop devices must be used in accordance with 5.3.8.3 of ISO 10218-2.<br> Protection stops occurring through HSS are designated as stop category 0.</p></li><li><p><strong>SSS</strong><br> This port is used to connect one or more protective stop devices through risk assessment.<br> Protective stop devices must be used in accordance with 5.3.8.3 of ISO 10218-2.<br> Protective stops that occur through SSS are designated as stop category 2.</p></li></ul>',9)])])}const f=s(r,[["render",c]]);export{_ as __pageData,f as default};
